/** အဆုံးသုံးမျက်နှာပြင်လေးခု၏ ရှဲလ်အခြေအနေ။ ဖိုင်သိုလှောင်ရာကို မျှဝေသော်လည်း လမ်း၊ ကိန်း၊ မှတ်တမ်းနှင့် အဝင်ကို ခွဲထားသည်။ */
public final class ဝင်းအသုံးပြုချိန်ပိုင်း {
    static int[] တန်ဖိုးထိန်းသိမ်း = new int[4 * 30000], ပြင်ဆင် = new int[4];
    static int လက်ရှိအချက်အလက်တစ်ခု, နေရာ;
    static boolean ဆက်လက်ဖတ်;
    static void အခင်းအကျင်းတန်ဖိုး(int[] ဒေတာ, boolean သိုလှောင်တန်ဖိုး) {
        for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < ဒေတာ.length; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++) { if (သိုလှောင်တန်ဖိုး) တန်ဖိုးထိန်းသိမ်း[နေရာ++] = ဒေတာ[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း]; else ဒေတာ[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း] = တန်ဖိုးထိန်းသိမ်း[နေရာ++]; }
    }
    static int တန်ဖိုး(int ဒေတာတန်ဖိုး, boolean သိုထားသလား) { if (သိုထားသလား) { တန်ဖိုးထိန်းသိမ်း[နေရာ++] = ဒေတာတန်ဖိုး; return ဒေတာတန်ဖိုး; } return တန်ဖိုးထိန်းသိမ်း[နေရာ++]; }
    static void နေရာနေရာရှာရွှေ့(int ထိန်းသိမ်းကွက်, boolean သိုထားသလား) {
        နေရာ = ထိန်းသိမ်းကွက် * 30000;
        အခင်းအကျင်းတန်ဖိုး(မှတ်ဉာဏ်ဖိုင်.လက်ရှိအချက်အလက်တစ်ခု, သိုထားသလား); မှတ်ဉာဏ်ဖိုင်.လက်ရှိအလျား = တန်ဖိုး(မှတ်ဉာဏ်ဖိုင်.လက်ရှိအလျား, သိုထားသလား);
        အခင်းအကျင်းတန်ဖိုး(အမိန့်ဝင်းသဒ္ဒါ.ကိန်းရှင်အမည်, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(အမိန့်ဝင်းသဒ္ဒါ.ကိန်းရှင်ဒေတာ, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(အမိန့်ဝင်းသဒ္ဒါ.အမည်အရှည်, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(အမိန့်ဝင်းသဒ္ဒါ.တန်ဖိုးအလျား, သိုထားသလား);
        အမိန့်ဝင်းသဒ္ဒါ.အခြေအနေတန်ဖိုး = တန်ဖိုး(အမိန့်ဝင်းသဒ္ဒါ.အခြေအနေတန်ဖိုး, သိုထားသလား);
        အခင်းအကျင်းတန်ဖိုး(စာကြောင်းပြင်.မှတ်တမ်းမှတ်တမ်းတစ်ခု, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(စာကြောင်းပြင်.မှတ်တမ်းအလျား, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(စာကြောင်းပြင်.သိုလှောင်တန်ဖိုး, သိုထားသလား); အခင်းအကျင်းတန်ဖိုး(အမိန့်အဓိပ္ပာယ်ဖော်.စာကြောင်း, သိုထားသလား);
        စာကြောင်းပြင်.မှတ်တမ်းအရေအတွက် = တန်ဖိုး(စာကြောင်းပြင်.မှတ်တမ်းအရေအတွက်, သိုထားသလား); စာကြောင်းပြင်.မှတ်တမ်းမှတ်တမ်းတစ်ခုအဆုံး = တန်ဖိုး(စာကြောင်းပြင်.မှတ်တမ်းမှတ်တမ်းတစ်ခုအဆုံး, သိုထားသလား);
        စာကြောင်းပြင်.တန်ဖိုးရှာဖွေ = တန်ဖိုး(စာကြောင်းပြင်.တန်ဖိုးရှာဖွေ, သိုထားသလား); စာကြောင်းပြင်.သိုထားအရှည် = တန်ဖိုး(စာကြောင်းပြင်.သိုထားအရှည်, သိုထားသလား);
        စာကြောင်းပြင်.အရွယ် = တန်ဖိုး(စာကြောင်းပြင်.အရွယ်, သိုထားသလား); စာကြောင်းပြင်.စာညွှန်းတန်ဖိုး = တန်ဖိုး(စာကြောင်းပြင်.စာညွှန်းတန်ဖိုး, သိုထားသလား); စာကြောင်းပြင်.ဝင်းစတင် = တန်ဖိုး(စာကြောင်းပြင်.ဝင်းစတင်, သိုထားသလား);
        ပြင်ဆင်[ထိန်းသိမ်းကွက်] = 1;
    }
    static void လုပ်ငန်းစဉ်တန်ဖိုးအချက်() {
        int ဖြစ်ရပ်ကိန်း = ဆားကစ်ပြား.အဆုံးသုံးမျက်နှာပြင်(12); if (ဖြစ်ရပ်ကိန်း == 0) return;
        နေရာနေရာရှာရွှေ့(လက်ရှိအချက်အလက်တစ်ခု, true);
        for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < 4; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++) {
            if ((ဖြစ်ရပ်ကိန်း & (1 << (8 + ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း))) != 0) { ဆားကစ်ပြား.ထိန်းချုပ်သုံးစွဲသူပရိုဂရမ်(32 + ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း); ပြင်ဆင်[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း] = 0; }
            if ((ဖြစ်ရပ်ကိန်း & (1 << (4 + ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း))) != 0 && ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း != လက်ရှိအချက်အလက်တစ်ခု) ပြင်ဆင်[ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း] = 0;
        }
        int နောက်တစ်ခုနေရာ = (ဖြစ်ရပ်ကိန်း & 15) - 1; if (နောက်တစ်ခုနေရာ < 0) နောက်တစ်ခုနေရာ = 0;
        if (ပြင်ဆင်[နောက်တစ်ခုနေရာ] == 0) for (int ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း = 0; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း < 30000; ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း++) တန်ဖိုးထိန်းသိမ်း[နောက်တစ်ခုနေရာ * 30000 + ထပ်ခါလည်ပတ်မှုအညွှန်းကိန်း] = 0;
        လက်ရှိအချက်အလက်တစ်ခု = နောက်တစ်ခုနေရာ; နေရာနေရာရှာရွှေ့(လက်ရှိအချက်အလက်တစ်ခု, false); ဆားကစ်ပြား.အဆုံးသုံးမျက်နှာပြင်(100 + လက်ရှိအချက်အလက်တစ်ခု); ဆက်လက်ဖတ် = true;
        အဆုံးသုံးစက်.ရေး("\nTERMINAL FOCUS "); အဆုံးသုံးစက်.ကိန်းတန်ဖိုး(လက်ရှိအချက်အလက်တစ်ခု + 1); အဆုံးသုံးစက်.အက္ခရာ(10);
    }
    static boolean လုပ်ဆောင်မှုပြန်စ() {
        if (ဆားကစ်ပြား.ထိန်းချုပ်သုံးစွဲသူပရိုဂရမ်(16 + လက်ရှိအချက်အလက်တစ်ခု) == 0) return false;
        အမိန့်ဝင်းဝင်ထွက်.အပြန်အလှန်ခွင့်ပြု = true; အမိန့်ဝင်းဝင်ထွက်.လုပ်ဆောင်(false, false); ဆားကစ်ပြား.အလှည့်ပြောင်းအဝင်အထွက်(1);
        int ကိုင်တွယ်ပြီးတန်ဖိုး = ဆားကစ်ပြား.ထိန်းချုပ်သုံးစွဲသူပရိုဂရမ်(လက်ရှိအချက်အလက်တစ်ခု); အမိန့်ဝင်းဝင်ထွက်.အဆုံး();
        if (ကိုင်တွယ်ပြီးတန်ဖိုး != -1005) { ဆက်လက်ဖတ် = false; အမိန့်ဝင်းသဒ္ဒါ.အခြေအနေတန်ဖိုး = ကိုင်တွယ်ပြီးတန်ဖိုး < 0 ? 126 : ကိုင်တွယ်ပြီးတန်ဖိုး; အဆုံးသုံးစက်.ရေး("exit "); အဆုံးသုံးစက်.ကိန်းတန်ဖိုး(ကိုင်တွယ်ပြီးတန်ဖိုး); အဆုံးသုံးစက်.အက္ခရာ(10); ဆားကစ်ပြား.အဆုံးသုံးမျက်နှာပြင်(3); }
        return true;
    }
}
